ON CONFLICT (id) DO UPDATE SET market_id = EXCLUDED.market_id, snapshot_id = EXCLUDED.snapshot_id, file_id = EXCLUDED.file_id, created_at = EXCLUDED.created_at;

-- notifications: 50 rows
ON CONFLICT (id) DO UPDATE SET market_id = EXCLUDED.market_id, record_link_id = EXCLUDED.record_link_id, event_key = EXCLUDED.event_key, kind = EXCLUDED.kind, message_code = EXCLUDED.message_code, created_at = EXCLUDED.created_at;

-- notification_recipients: 50 rows
ON CONFLICT (id) DO UPDATE SET market_id = EXCLUDED.market_id, notification_id = EXCLUDED.notification_id, read_at = EXCLUDED.read_at, user_id = EXCLUDED.user_id, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at, version = EXCLUDED.version;

-- audit_events: 50 rows
ON CONFLICT (id) DO UPDATE SET market_id = EXCLUDED.market_id, actor_id = EXCLUDED.actor_id, action = EXCLUDED.action, resource_type = EXCLUDED.resource_type, resource_id = EXCLUDED.resource_id, resource_version = EXCLUDED.resource_version, request_id = EXCLUDED.request_id, reason = EXCLUDED.reason, safe_diff = EXCLUDED.safe_diff, result = EXCLUDED.result, occurred_at = EXCLUDED.occurred_at, created_at = EXCLUDED.created_at;

-- idempotency_records: 50 rows
ON CONFLICT (id) DO UPDATE SET market_id = EXCLUDED.market_id, actor_id = EXCLUDED.actor_id, operation = EXCLUDED.operation, key = EXCLUDED.key, request_hash = EXCLUDED.request_hash, http_status = EXCLUDED.http_status, result_type = EXCLUDED.result_type, result_id = EXCLUDED.result_id, expires_at = EXCLUDED.expires_at, created_at = EXCLUDED.created_at;

